// Isaiah, 25 Nov: Rasaam's program, generated by his coach from his answers,
// saved with all 80 rows as "Unknown Exercise". The save turns library ids
// back into names, and the generated names had never been made into library
// entries. Now they are first, and a save that would write nameless rows stops.
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { load } from "./extract.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const APP = path.join(here, "..", "src", "App.jsx");
const src = fs.readFileSync(APP, "utf8");
const H = await load(APP, [
  { name: "PHASES", kind: "const" }, { name: "phaseIndex", kind: "const" }, "buildDaysWithExerciseIds", "denormalizeByWeek", "denormalizeDays",
]);
let passed = 0; const tests = []; const test = (n, f) => tests.push([n, f]);

const generated = { days: [{ name: "Day 1 — Upper", exercises: [
  { phase: "warmup_general", name: "Jump Rope", sets: 1, reps: "3 min" },
  { phase: "explosive", name: "Broad Jump", sets: 3, reps: "3-5", note: "Land soft" },
  { phase: "compound", name: "Trap Bar Deadlift", sets: 4, reps: "5" },
] }] };

test("names survive the trip: generated, made into library entries, saved", () => {
  const state = { exercises: [{ id: "e1", name: "Trap Bar Deadlift" }] };
  const { days, newExercises } = H.buildDaysWithExerciseIds(generated.days, state, { sortByPhase: true });
  const saved = H.denormalizeDays(days, { ...state, exercises: [...state.exercises, ...newExercises] });
  assert.deepEqual(saved[0].exercises.map(x => x.name), ["Jump Rope", "Broad Jump", "Trap Bar Deadlift"]);
  assert.equal(saved[0].exercises[1].note, "Land soft");
});

test("what went wrong before: saving the generated days straight through loses every name", () => {
  const saved = H.denormalizeDays(generated.days, { exercises: [] });
  assert.ok(saved[0].exercises.every(x => x.name === "Unknown Exercise"));
});

test("the coach's generate-from-answers save makes the library entries first", () => {
  assert.ok(src.includes("const { days: withIds, newExercises: minted } = buildDaysWithExerciseIds(template.days, state, { sortByPhase: true });"));
  assert.ok(src.includes("state: { ...state, exercises: [...state.exercises, ...minted] }, allowEmpty,"));
});

test("a save that would write nameless rows stops instead", () => {
  assert.ok(src.includes('filter(x => x.name === "Unknown Exercise").length'));
  assert.ok(src.includes("so nothing was saved"));
});

for (const [name, fn] of tests) {
  try { await fn(); passed++; } catch (err) { console.error(`FAIL  ${name}\n      ${err.message}`); process.exitCode = 1; }
}
console.log(`${passed}/${tests.length} passed`);
